// Actual App consumes byte-exact fictional DTOs generated by genuine controllers.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {chromium} from 'playwright';
import {startFixture,fingerprint,repo} from '../fixtures/care-map-floating-canvas/runtime.mjs';
const out=process.argv.find(value=>value.startsWith('--out='))?.slice(6)||await fs.mkdtemp(path.join(os.tmpdir(),'care-map-scoped-dto-'));
await fs.mkdir(out,{recursive:true});
const directory=fileURLToPath(new URL('../fixtures/care-map-area-resources/server-dto/',import.meta.url));
const manifest=JSON.parse(await fs.readFile(path.join(directory,'manifest.json'),'utf8'));
const report={boundary:'Actual local App with genuine server-controller fictional DTO bytes. Only owner-route map ID is adapted to the existing loopback fixture; places, pins, assets, notes, fields, scope and coordinates are unchanged. No handwritten projection, production data, auth/session actions, saved mutations or map gestures.',producerManifest:manifest,sourceBefore:await fingerprint(),cases:[]};
let fixture,browser;
async function until(fn,message){const end=Date.now()+12000;while(Date.now()<end){if(await fn())return;await new Promise(resolve=>setTimeout(resolve,40));}throw Error(message);}
try{
 for(const[filename,expected]of Object.entries(manifest.files)){const data=await fs.readFile(path.join(directory,filename));assert.equal(data.length,expected.bytes);assert.equal(createHash('sha256').update(data).digest('hex'),expected.sha256);}
 for(const[filename,expected]of Object.entries(manifest.runtime))assert.equal(createHash('sha256').update(await fs.readFile(path.join(repo,filename))).digest('hex'),expected,'producer runtime must match tested runtime: '+filename);
 fixture=await startFixture(out);browser=await chromium.launch({headless:true});
 for(const profile of ['owner-selected','shared-selected','owner-unavailable','shared-withdrawn']){
  const context=await browser.newContext({viewport:{width:1470,height:801}}),page=await context.newPage();let state;
  try{
   const raw=await fs.readFile(path.join(directory,profile+'.json')),dto=JSON.parse(raw);state=await fixture.install(page,{annotations:[]});
   const shared=profile.startsWith('shared'),expected=profile.endsWith('selected')?1:0;
   if(shared)await page.route('**/api/shared-maps/fictional-scoped-dto',route=>route.fulfill({body:raw,contentType:'application/json'}));
   else state.directory={...dto,id:fixture.mapId};
   await page.goto(new URL(shared?'/shared/maps/fictional-scoped-dto':'/my-directory/maps/'+fixture.mapId,fixture.base).href);
   await page.getByText(dto.name,{exact:true}).first().waitFor({state:'attached'});
   if(expected)await until(()=>page.evaluate(()=>[...window.__qaMaps].some(map=>map.getContainer().isConnected&&Object.values(map._layers).some(layer=>layer.options?.icon&&typeof layer.getLatLng==='function'))),'actual selected resource marker not rendered');
   else await page.waitForTimeout(400);
   const rendered=await page.evaluate(()=>{const maps=[...window.__qaMaps].filter(map=>map.getContainer().isConnected&&map.getContainer().getBoundingClientRect().width>0);return maps.flatMap(map=>Object.values(map._layers).filter(layer=>layer.options?.icon&&typeof layer.getLatLng==='function').map(layer=>{const p=layer.getLatLng();return{lat:p.lat,lng:p.lng,pane:layer.options.pane};}));});
   assert.equal(rendered.length,expected);for(const point of rendered){assert.equal(point.lat,1.38);assert.equal(point.lng,103.75);}
   const body=await page.locator('body').innerText();assert.doesNotMatch(body,/Fictional outside venue|Fictional outside address/);
   if(profile==='shared-withdrawn')assert.doesNotMatch(body,/Fictional inside venue|Fictional inside address/);
   if(profile==='owner-unavailable')assert.match(body,/Selected venue unavailable|unavailable/i);
   assert.deepEqual(state.errors,[]);assert.deepEqual(state.unexpectedWrites,[]);assert.equal(state.allowedWrites.length,0);
   const screenshot=path.join(out,profile+'.png');await page.screenshot({path:screenshot});
   report.cases.push({profile,passed:true,dtoSha256:createHash('sha256').update(raw).digest('hex'),mapIdAdaptation:shared?null:{from:dto.id,to:fixture.mapId},expectedNativeMarkers:expected,rendered,noOutsideOrPrivateFallback:true,savedWrites:0,screenshot});
  }catch(error){report.cases.push({profile,passed:false,error:error.stack});await fs.writeFile(path.join(out,profile+'-failure-dom.txt'),await page.locator('body').innerText()).catch(()=>{});await page.screenshot({path:path.join(out,profile+'-failure.png')}).catch(()=>{});}
  finally{await context.close();}
 }
}catch(error){report.failure=error.stack;process.exitCode=1;}
finally{report.sourceAfter=await fingerprint();report.sourceUnchanged=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.summary={passed:report.cases.filter(value=>value.passed).length,failed:report.cases.filter(value=>!value.passed).length};if(report.failure||report.summary.failed||!report.sourceUnchanged)process.exitCode=1;await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2)+'\n');await browser?.close();await fixture?.server.close();console.log(JSON.stringify({out,summary:report.summary,failure:report.failure,sourceUnchanged:report.sourceUnchanged}));}
